//! The suite has teeth: each defect planted in the mock fails the scenario written for
//! it. The defects are every one the audits found in a plausible engine or viewer.
//! Against the honest mock every scenario passes (`adversary.rs`).

#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::sync::Arc;

use nfx_pay::adversary;
use nfx_pay::mock::{MockHarness, SeederFlaw as S, ViewerFlaw as V};

macro_rules! catches {
    ($($test:ident: $harness:expr => $scenario:ident),* $(,)?) => {
        $(
            #[test]
            fn $test() {
                // The defect must fail a check of the suite: a hang, a panic raised in the
                // engine, the harness or a runtime, or one at a line of the suite that makes
                // no check (a bare unwrap), names no behaviour, so none is a catch. The time
                // allowed is the suite's own, and so is the way it is run: a late catch under
                // load is not taken for a hang.
                let run = nfx_pay::run_scenario!(adversary::$scenario(&$harness));
                match &run {
                    adversary::Ran::Finished => panic!(
                        "{} did not catch the planted defect",
                        stringify!($scenario)
                    ),
                    adversary::Ran::Hung => {
                        panic!("{} hung on the planted defect", stringify!($scenario))
                    }
                    adversary::Ran::Panicked { file, line, .. } => assert!(
                        run.failed_the_suite(),
                        "{} failed no check of the suite: it panicked at {file}:{line}",
                        stringify!($scenario)
                    ),
                }
            }
        )*
    };
}

/// A flawed seeder whose mint answers every call in the poll that sends it. Some two hundred
/// seeder defects, all older than the twenty-ninth audit, are registered here alone. The
/// thirtieth audit ran each of them once on round trips and once on woken answers: every
/// one fails a check of the suite there too, the same check on both. So a second and a third
/// entry for each would add time and no teeth; a defect that could behave otherwise where
/// an answer spans polls is registered on those harnesses too.
fn s(flaw: S) -> MockHarness {
    MockHarness::with_seeder_flaw(flaw)
}

fn v(flaw: V) -> MockHarness {
    MockHarness::with_viewer_flaw(flaw)
}

/// A flawed seeder whose mint answers reads on a later poll. Most defects registered here
/// are registered on the synchronous harness too, and must fail the suite on round trips as
/// well; the rest the suite can show only where a read spans polls of its entry. A read is
/// abandoned only as its entry is dropped between sending it and its return, and a
/// synchronous read returns in the poll that sends it. A payment that took a dead turn over
/// waits on no read but its own: of its second, only a `hello`'s read can come before it,
/// and that serves no payment. And a read back while a later second's read is still out
/// needs one held read to return before another: reads the mint holds on threads go on
/// together, or each as its own wait ends, in an order real time alone sets.
fn r(flaw: S) -> MockHarness {
    MockHarness::with_seeder_flaw_round_trip(flaw)
}

/// A flawed seeder whose mint answers every call its entries and sweeps await (a read, a
/// swap, a key request, a keyset listing) from another thread a few milliseconds later,
/// waking its caller, as a real mint's answer comes back. Most defects registered here fail
/// the check they fail on round trips; a few fail another, in the scenario each is
/// registered with; and a few have no round-trip entry, among them each read sent without
/// asking to be woken (`S::ReadUnwoken` and the like): on round trips such a read is back at
/// its reader's next poll all the same.
fn w(flaw: S) -> MockHarness {
    MockHarness::with_seeder_flaw_woken(flaw)
}

/// The same, the seeder settling each swap's outcome on a task of its own, on the runtime
/// the scenario runs in: for defects that can arise only where the seeder has such tasks,
/// one of which wakes an entry before it settles what the wake announces. The other
/// defects registered here, each of a wake that never comes, are registered with another
/// harness too: they must fail against such a seeder as well.
fn t(flaw: S) -> MockHarness {
    let rt = tokio::runtime::Handle::current();
    MockHarness::with_seeder_flaw_on_tasks(
        flaw,
        Arc::new(move |task| {
            rt.spawn(task);
        }),
    )
}

/// A flawed seeder that asks every quoted mint for its keyset listing at its start too, as
/// a seeder may (`tests/listings_at_start.rs`): each defect of keys, keyset listings and the
/// keyset rule registered here fails the suite against such a seeder too, at a check of its
/// own behaviour, and so do the defects only a seeder that asks at its start can show.
fn l(flaw: S) -> MockHarness {
    MockHarness::with_seeder_flaw_at_start(flaw)
}

